BEGIN;
CREATE OR REPLACE FUNCTION incident_communication_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'incident communication history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS incident_communication_scopes (scope_hash text PRIMARY KEY CHECK(scope_hash ~ '^[a-f0-9]{64}$'),operator_test_id text NOT NULL,tenant_fingerprint text NOT NULL,incident_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(operator_test_id,tenant_fingerprint,incident_id));
CREATE TABLE IF NOT EXISTS incident_communication_policies (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),policy_hash text PRIMARY KEY CHECK(policy_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_revisions (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),revision_hash text PRIMARY KEY CHECK(revision_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_audiences (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),resolution_hash text PRIMARY KEY CHECK(resolution_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_messages (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),message_hash text PRIMARY KEY CHECK(message_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_outbox (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),row_hash text PRIMARY KEY CHECK(row_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_deliveries (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_acknowledgements (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_transitions (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),transition_hash text PRIMARY KEY CHECK(transition_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_decisions (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),decision_hash text PRIMARY KEY CHECK(decision_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_conflicts (scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),conflict_hash text PRIMARY KEY CHECK(conflict_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_communication_request_claims (operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS incident_communication_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id),scope_hash text NOT NULL REFERENCES incident_communication_scopes(scope_hash),decision_hash text NOT NULL REFERENCES incident_communication_decisions(decision_hash),created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['incident_communication_scopes','incident_communication_policies','incident_communication_revisions','incident_communication_audiences','incident_communication_messages','incident_communication_outbox','incident_communication_deliveries','incident_communication_acknowledgements','incident_communication_transitions','incident_communication_decisions','incident_communication_conflicts','incident_communication_request_claims','incident_communication_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I',item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION incident_communication_reject_mutation()',item,item); END LOOP; END $$;
COMMIT;
